import"./strings.m.js";import"//os-feedback/help_content.js";import{loadTimeData}from"//resources/ash/common/load_time_data.m.js";import{ColorChangeUpdater}from"//resources/cr_components/color_change_listener/colors_css_updater.js";import{assert}from"//resources/js/assert.js";const OS_FEEDBACK_TRUSTED_ORIGIN="chrome://os-feedback";function initialize(){const helpContent=document.querySelector("help-content");assert(!!helpContent);window.addEventListener("message",(event=>{if(event.origin!==OS_FEEDBACK_TRUSTED_ORIGIN){console.error("Unknown origin: "+event.origin);return}helpContent.searchResult=event.data;window.parent.postMessage({id:"help-content-received-for-testing",count:event.data.contentList.length},OS_FEEDBACK_TRUSTED_ORIGIN)}));if(loadTimeData.getBoolean("isJellyEnabledForOsFeedback")){document.querySelector("link[href*='cros_styles.css']")?.setAttribute("href","//theme/colors.css?sets=legacy,sys");const typographyLink=document.createElement("link");typographyLink.href="//theme/typography.css";typographyLink.rel="stylesheet";document.head.appendChild(typographyLink);document.body.classList.add("jelly-enabled");ColorChangeUpdater.forDocument().start();window.parent.postMessage({id:"color-change-updater-started-for-testing"},OS_FEEDBACK_TRUSTED_ORIGIN)}}document.addEventListener("DOMContentLoaded",initialize);